_tables_ready = False


def ensure_ops_tables():
    global _tables_ready
    if _tables_ready:
        return
    try:
        MissionTask.__table__.create(bind=db.engine, checkfirst=True)
        MissionRosterEntry.__table__.create(bind=db.engine, checkfirst=True)
        MissionSubject.__table__.create(bind=db.engine, checkfirst=True)
        MissionOpPeriod.__table__.create(bind=db.engine, checkfirst=True)
        MissionHqDecision.__table__.create(bind=db.engine, checkfirst=True)
        _tables_ready = True
    except Exception as e:
        logger.warning("mission ops tables ensure failed: %s", e)


def _mission_or_404(name: str):
    return db.session.execute(db.session.query(Mission).filter_by(name=name)).scalar_one_or_none()


def _parse_dt(val):
    if not val:
        return None
    if isinstance(val, datetime):
        return val
    try:
        return date_parser.isoparse(str(val))
    except Exception:
        try:
            return datetime.fromisoformat(str(val).replace("Z", "+00:00"))
        except Exception:
            return None


def _publish_mission_log_cot(entry: MissionLogEntry):
    """Notify ATAK mission subscribers (same channel as Marti create_log_entry)."""
    try:
        change_cot = entry.generate_cot()
        body = json.dumps(
            {
                "uid": entry.creator_uid or "psr-hq",
                "cot": tostring(change_cot).decode("utf-8"),
            }
        )
        rabbit_credentials = pika.PlainCredentials(
            app.config.get("OTS_RABBITMQ_USERNAME"),
            app.config.get("OTS_RABBITMQ_PASSWORD"),
        )
        rabbit_host = app.config.get("OTS_RABBITMQ_SERVER_ADDRESS")
        rabbit_connection = pika.BlockingConnection(
            pika.ConnectionParameters(host=rabbit_host, credentials=rabbit_credentials)
        )
        channel = rabbit_connection.channel()
        channel.basic_publish(
            "missions",
            routing_key=f"missions.{entry.mission_name}",
            body=body,
        )
        channel.close()
        rabbit_connection.close()
    except Exception as e:
        logger.warning("mission log RabbitMQ publish failed: %s", e)


def _add_mission_log(
    mission_name: str,
    content: str,
    keywords: list,
    content_hashes: list | None = None,
):
    try:
        try:
            creator = getattr(current_user, "username", None) or "psr-hq"
        except Exception:
            creator = "psr-hq"
        entry = MissionLogEntry()
        entry.content = (content or "")[:255]
        entry.creator_uid = creator
        entry.entry_uid = str(uuid.uuid4())
        entry.mission_name = mission_name
        entry.keywords = keywords or []
        if content_hashes:
            entry.content_hashes = content_hashes
        now = datetime.now(timezone.utc)
        entry.server_time = now
        entry.dtg = now
        entry.created = now
        db.session.add(entry)
        db.session.commit()
        socketio.emit(
            "mission_log",
            entry.to_json(),
            namespace="/socket.io",
            room=mission_name,
        )
        _publish_mission_log_cot(entry)
    except Exception as e:
        logger.error("mission log for ops failed: %s", e)
        db.session.rollback()


def _deactivate_other_subjects(mission_name: str, keep_uid: str | None):
    rows = (
        db.session.execute(
            db.session.query(MissionSubject).filter_by(mission_name=mission_name, status="active")
        )
        .scalars()
        .all()
    )
    now = datetime.now(timezone.utc)
    for row in rows:
        if keep_uid and row.uid == keep_uid:
            continue
        row.status = "cancelled"
        row.updated = now


def _store_subject_photo_zip(file_storage, preferred_name: str) -> tuple[str, str]:
    """Save image as DataPackage zip; return (sha256, inner_filename)."""
    raw = file_storage.read()
    if not raw:
        raise ValueError("empty file")
    orig = secure_filename(file_storage.filename or preferred_name) or preferred_name
    base, ext = os.path.splitext(orig)
    if not ext:
        ext = ".jpg"
    inner_name = f"{base or 'subject'}{ext}"
    md5 = hashlib.md5(raw).hexdigest()
    buf = BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        zf.writestr(f"{md5}/{inner_name}", raw)
        manifest = (
            '<?xml version="1.0" encoding="UTF-8"?>'
            '<MissionPackageManifest version="2">'
            "<Configuration>"
            f'<Parameter name="uid" value="{uuid.uuid4()}"/>'
            f'<Parameter name="name" value="psr-subject-{inner_name}"/>'
            "</Configuration>"
            "<Contents>"
            f'<Content ignore="false" zipEntry="{md5}/{inner_name}"/>'
            "</Contents>"
            "</MissionPackageManifest>"
        )
        zf.writestr("MANIFEST/manifest.xml", manifest)
    zip_bytes = buf.getvalue()
    file_hash = hashlib.sha256(zip_bytes).hexdigest()
    upload_folder = app.config.get("UPLOAD_FOLDER")
    os.makedirs(upload_folder, exist_ok=True)
    with open(os.path.join(upload_folder, f"{file_hash}.zip"), "wb") as f:
        f.write(zip_bytes)

    existing_dp = db.session.execute(
        db.session.query(DataPackage).filter_by(hash=file_hash)
    ).scalar_one_or_none()
    if not existing_dp:
        dp = DataPackage()
        dp.filename = f"psr-subject-{file_hash[:12]}.zip"
        dp.hash = file_hash
        dp.submission_time = datetime.now(timezone.utc)
        dp.mime_type = "application/zip"
        dp.size = len(zip_bytes)
        dp.submission_user = getattr(current_user, "id", None)
        dp.creator_uid = None
        dp.keywords = "psr:subject"
        db.session.add(dp)

    existing_mc = db.session.execute(
        db.session.query(MissionContent).filter_by(hash=file_hash)
    ).scalar_one_or_none()
    if not existing_mc:
        mc = MissionContent()
        mc.mime_type = "application/zip"
        mc.filename = f"psr-subject-{inner_name}.zip"
        mc.submission_time = datetime.now(timezone.utc)
        mc.submitter = getattr(current_user, "username", None) or "psr-hq"
        mc.uid = str(uuid.uuid4())
        mc.creator_uid = getattr(current_user, "username", None) or "psr-hq"
        mc.size = len(zip_bytes)
        mc.expiration = -1
        mc.keywords = ["psr:subject"]
        mc.hash = file_hash
        db.session.add(mc)

    return file_hash, inner_name


def _attach_hash_to_mission(mission_name: str, content_hash: str):
    content = db.session.execute(
        db.session.query(MissionContent).filter_by(hash=content_hash)
    ).scalar_one_or_none()
    if not content:
        return
    link = db.session.execute(
        db.session.query(MissionContentMission).filter_by(
            mission_content_id=content.id, mission_name=mission_name
        )
    ).scalar_one_or_none()
    if not link:
        link = MissionContentMission()
        link.mission_name = mission_name
        link.mission_content_id = content.id
        db.session.add(link)


def _scan_task_due(mission_name: str | None = None, warn_seconds: int = 1800) -> list[dict]:
    """Persist overdue status; MissionLog + socket once per transition."""
    ensure_ops_tables()
    q = db.session.query(MissionTask).filter(
        MissionTask.status.in_(("issued", "acked")),
        MissionTask.return_by.isnot(None),
    )
    if mission_name:
        q = q.filter(MissionTask.mission_name == mission_name)
    rows = db.session.execute(q).scalars().all()
    now = datetime.utcnow()
    newly = []
    for task in rows:
        rb = task._return_by_naive()
        if not rb or rb >= now:
            continue
        task.status = "overdue"
        task.updated = datetime.now(timezone.utc)
        try:
            db.session.commit()
        except Exception as e:
            logger.error("task due persist failed: %s", e)
            db.session.rollback()
            continue
        who = task.assignee or "—"
        _add_mission_log(
            task.mission_name,
            f"Просрочен возврат: {task.title} ({who})",
            ["psr:due", f"uid:{task.uid}"],
        )
        payload = task.to_json(warn_seconds)
        socketio.emit("mission_task", payload, namespace="/socket.io")
        socketio.emit("mission_task_due", payload, namespace="/socket.io")
        newly.append(payload)
    return newly


def _due_buckets(mission_name: str, warn_seconds: int = 1800) -> dict:
    _scan_task_due(mission_name, warn_seconds)
    rows = (
        db.session.execute(
            db.session.query(MissionTask)
            .filter_by(mission_name=mission_name)
            .order_by(MissionTask.return_by.asc())
        )
        .scalars()
        .all()
    )
    overdue, warning, timed = [], [], []
    for t in rows:
        j = t.to_json(warn_seconds)
        ds = j.get("due_state")
        if ds == "overdue":
            overdue.append(j)
        elif ds == "warn":
            warning.append(j)
        elif ds == "ok":
            timed.append(j)
    return {
        "success": True,
        "warn_seconds": warn_seconds,
        "overdue": overdue,
        "warning": warning,
        "timed": timed,
        "overdue_count": len(overdue),
        "warning_count": len(warning),
    }


_due_job_ready = False


def _ensure_due_scheduler():
    """Interval scan without patching OTS defaultconfig JOBS."""
    global _due_job_ready
    if _due_job_ready:
        return
    try:
        from opentakserver.extensions import apscheduler

        if not getattr(apscheduler, "running", False):
            return

        def _job():
            with apscheduler.app.app_context():
                _scan_task_due()

        existing = apscheduler.get_job("psr_scan_task_due")
        if not existing:
            apscheduler.add_job(
                id="psr_scan_task_due",
                func=_job,
                trigger="interval",
                minutes=1,
                replace_existing=True,
            )
        _due_job_ready = True
    except Exception as e:
        logger.debug("psr due scheduler skip: %s", e)


