@mission_ops_api.route("/api/missions/<path:mission_name>/roster", methods=["POST"])
@auth_required()
def create_roster(mission_name):
    ensure_ops_tables()
    if not _mission_or_404(mission_name):
        return jsonify({"success": False, "error": gettext("Mission not found")}), 404
    body = request.get_json(silent=True) or {}
    name = (body.get("display_name") or body.get("callsign") or "").strip()
    if not name:
        return jsonify({"success": False, "error": gettext("Name required")}), 400
    now = datetime.now(timezone.utc)
    uid = body.get("uid") or str(uuid.uuid4())
    status = (body.get("status") or "expected")[:32]
    entry = MissionRosterEntry(
        uid=uid,
        mission_name=mission_name,
        display_name=name[:255],
        callsign=(body.get("callsign") or None),
        eud_uid=(body.get("eud_uid") or None),
        username=(body.get("username") or None),
        phone=(body.get("phone") or None),
        transport=(body.get("transport") or None),
        skills=(body.get("skills") or None),
        role_on_op=(body.get("role_on_op") or None),
        status=status,
        check_in_at=now if status in ("arrived", "deployed") else _parse_dt(body.get("check_in_at")),
        notes=(body.get("notes") or None),
        created=now,
        updated=now,
    )
    db.session.add(entry)
    db.session.commit()
    payload = entry.to_json()
    socketio.emit("mission_roster", payload, namespace="/socket.io")
    return jsonify({"success": True, "entry": payload})


@mission_ops_api.route("/api/missions/<path:mission_name>/roster/<uid>", methods=["PATCH"])
@auth_required()
def patch_roster(mission_name, uid):
    ensure_ops_tables()
    entry = db.session.execute(
        db.session.query(MissionRosterEntry).filter_by(mission_name=mission_name, uid=uid)
    ).scalar_one_or_none()
    if not entry:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    for field in (
        "display_name",
        "callsign",
        "eud_uid",
        "username",
        "phone",
        "transport",
        "skills",
        "role_on_op",
        "notes",
    ):
        if field in body:
            setattr(entry, field, body[field])
    if "status" in body and body["status"]:
        entry.status = str(body["status"])[:32]
        if entry.status in ("arrived", "deployed") and not entry.check_in_at:
            entry.check_in_at = datetime.now(timezone.utc)
    if "check_in_at" in body:
        entry.check_in_at = _parse_dt(body["check_in_at"])
    entry.updated = datetime.now(timezone.utc)
    db.session.commit()
    payload = entry.to_json()
    socketio.emit("mission_roster", payload, namespace="/socket.io")
    return jsonify({"success": True, "entry": payload})


