@mission_ops_api.route("/api/missions/<path:mission_name>/roster/seed_online", methods=["POST"])
@auth_required()
def seed_roster_from_euds(mission_name):
    """Add Connected EUDs that are not yet on the roster (idempotent by callsign)."""
    ensure_ops_tables()
    if not _mission_or_404(mission_name):
        return jsonify({"success": False, "error": gettext("Mission not found")}), 404
    existing = {
        (e.callsign or "").lower()
        for e in db.session.execute(
            db.session.query(MissionRosterEntry).filter_by(mission_name=mission_name)
        )
        .scalars()
        .all()
        if e.callsign
    }
    added = []
    now = datetime.now(timezone.utc)
    euds = db.session.execute(db.session.query(EUD)).scalars().all()
    for eud in euds:
        if getattr(eud, "last_status", None) != "Connected":
            continue
        cs = (eud.callsign or "").strip()
        if not cs or cs.lower() in existing:
            continue
        entry = MissionRosterEntry(
            uid=str(uuid.uuid4()),
            mission_name=mission_name,
            display_name=cs,
            callsign=cs,
            eud_uid=eud.uid,
            phone=getattr(eud, "phone_number", None),
            status="arrived",
            check_in_at=now,
            created=now,
            updated=now,
        )
        db.session.add(entry)
        added.append(entry)
        existing.add(cs.lower())
    db.session.commit()
    for e in added:
        socketio.emit("mission_roster", e.to_json(), namespace="/socket.io")
    return jsonify({"success": True, "added": len(added), "results": [e.to_json() for e in added]})


