@mission_ops_api.route("/api/missions/<path:mission_name>/subject", methods=["POST"])
@auth_required()
def create_subject(mission_name):
    ensure_ops_tables()
    if not _mission_or_404(mission_name):
        return jsonify({"success": False, "error": gettext("Mission not found")}), 404
    body = request.get_json(silent=True) or {}
    full_name = (body.get("full_name") or "").strip()
    if not full_name:
        return jsonify({"success": False, "error": gettext("Name required")}), 400
    now = datetime.now(timezone.utc)
    uid = body.get("uid") or str(uuid.uuid4())
    status = (body.get("status") or "active")[:32]
    if status == "active":
        _deactivate_other_subjects(mission_name, keep_uid=uid)
    subj = MissionSubject(
        uid=uid,
        mission_name=mission_name,
        full_name=full_name[:255],
        aliases=(body.get("aliases") or None),
        age=(str(body["age"])[:32] if body.get("age") is not None else None),
        sex=(body.get("sex") or None),
        clothing=(body.get("clothing") or None),
        appearance=(body.get("appearance") or None),
        distinguishing=(body.get("distinguishing") or None),
        medical=(body.get("medical") or None),
        last_seen_at=_parse_dt(body.get("last_seen_at")),
        last_seen_place=(body.get("last_seen_place") or None),
        notes=(body.get("notes") or None),
        photo_hash=(body.get("photo_hash") or None),
        photo_filename=(body.get("photo_filename") or None),
        status=status,
        created_by=getattr(current_user, "username", None),
        created=now,
        updated=now,
    )
    db.session.add(subj)
    db.session.commit()
    hashes = [subj.photo_hash] if subj.photo_hash else None
    _add_mission_log(
        mission_name,
        f"Ориентировка: {full_name}",
        ["psr:subject", f"uid:{uid}"],
        content_hashes=hashes,
    )
    payload = subj.to_json()
    socketio.emit("mission_subject", payload, namespace="/socket.io")
    return jsonify({"success": True, "subject": payload})


@mission_ops_api.route("/api/missions/<path:mission_name>/subject/<uid>", methods=["PATCH"])
@auth_required()
def patch_subject(mission_name, uid):
    ensure_ops_tables()
    subj = db.session.execute(
        db.session.query(MissionSubject).filter_by(mission_name=mission_name, uid=uid)
    ).scalar_one_or_none()
    if not subj:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    for field in (
        "full_name",
        "aliases",
        "age",
        "sex",
        "clothing",
        "appearance",
        "distinguishing",
        "medical",
        "last_seen_place",
        "notes",
        "photo_hash",
        "photo_filename",
    ):
        if field in body:
            val = body[field]
            if field == "full_name" and val:
                val = str(val)[:255]
            if field == "age" and val is not None:
                val = str(val)[:32]
            setattr(subj, field, val)
    if "last_seen_at" in body:
        subj.last_seen_at = _parse_dt(body["last_seen_at"])
    if "status" in body and body["status"]:
        subj.status = str(body["status"])[:32]
        if subj.status == "active":
            _deactivate_other_subjects(mission_name, keep_uid=uid)
    subj.updated = datetime.now(timezone.utc)
    db.session.commit()
    hashes = [subj.photo_hash] if subj.photo_hash else None
    _add_mission_log(
        mission_name,
        f"Ориентировка обновлена: {subj.full_name} [{subj.status}]",
        ["psr:subject", f"uid:{uid}"],
        content_hashes=hashes,
    )
    payload = subj.to_json()
    socketio.emit("mission_subject", payload, namespace="/socket.io")
    return jsonify({"success": True, "subject": payload})


