@mission_ops_api.route(
    "/api/missions/<path:mission_name>/subject/<uid>/photo", methods=["POST"]
)
@auth_required()
def upload_subject_photo(mission_name, uid):
    ensure_ops_tables()
    subj = db.session.execute(
        db.session.query(MissionSubject).filter_by(mission_name=mission_name, uid=uid)
    ).scalar_one_or_none()
    if not subj:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    f = request.files.get("file") or request.files.get("photo")
    if not f:
        return jsonify({"success": False, "error": gettext("No file")}), 400
    try:
        file_hash, inner_name = _store_subject_photo_zip(f, "subject.jpg")
        _attach_hash_to_mission(mission_name, file_hash)
        subj.photo_hash = file_hash
        subj.photo_filename = inner_name
        subj.updated = datetime.now(timezone.utc)
        db.session.commit()
    except Exception as e:
        logger.error("subject photo upload failed: %s", e)
        db.session.rollback()
        return jsonify({"success": False, "error": str(e)}), 500
    _add_mission_log(
        mission_name,
        f"Ориентировка фото: {subj.full_name}",
        ["psr:subject", f"uid:{uid}"],
        content_hashes=[file_hash],
    )
    payload = subj.to_json()
    socketio.emit("mission_subject", payload, namespace="/socket.io")
    return jsonify({"success": True, "subject": payload})


@mission_ops_api.route(
    "/api/missions/<path:mission_name>/subject/<uid>/photo", methods=["GET"]
)
@auth_required()
def get_subject_photo(mission_name, uid):
    """Serve first image from the subject's data-package zip."""
    ensure_ops_tables()
    subj = db.session.execute(
        db.session.query(MissionSubject).filter_by(mission_name=mission_name, uid=uid)
    ).scalar_one_or_none()
    if not subj or not subj.photo_hash:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    zip_path = os.path.join(app.config.get("UPLOAD_FOLDER"), f"{subj.photo_hash}.zip")
    if not os.path.isfile(zip_path):
        return jsonify({"success": False, "error": gettext("File missing")}), 404
    with zipfile.ZipFile(zip_path, "r") as zf:
        for name in zf.namelist():
            lower = name.lower()
            if lower.endswith((".jpg", ".jpeg", ".png", ".webp")):
                data = zf.read(name)
                mime = "image/jpeg"
                if lower.endswith(".png"):
                    mime = "image/png"
                elif lower.endswith(".webp"):
                    mime = "image/webp"
                return send_file(
                    BytesIO(data), mimetype=mime, download_name=os.path.basename(name)
                )
    return jsonify({"success": False, "error": gettext("No image in package")}), 404


