@mission_ops_api.route("/api/missions/<path:mission_name>/decisions", methods=["POST"])
@auth_required()
def create_decision(mission_name):
    ensure_ops_tables()
    if not _mission_or_404(mission_name):
        return jsonify({"success": False, "error": gettext("Mission not found")}), 404
    body = request.get_json(silent=True) or {}
    text = (body.get("body") or "").strip()
    if not text:
        return jsonify({"success": False, "error": gettext("Body required")}), 400
    cat = (body.get("category") or "decision").strip()[:32]
    if cat not in _DECISION_CATEGORIES:
        cat = "decision"
    now = datetime.now(timezone.utc)
    uid = body.get("uid") or str(uuid.uuid4())
    row = MissionHqDecision(
        uid=uid,
        mission_name=mission_name,
        category=cat,
        body=text,
        created_by=getattr(current_user, "username", None),
        created=now,
        updated=now,
    )
    db.session.add(row)
    db.session.commit()
    # Short audit line in mission log (≤255); full text stays in HQ journal only.
    preview = text if len(text) <= 180 else text[:177] + "…"
    _add_mission_log(
        mission_name,
        f"Решение штаба [{cat}]: {preview}",
        ["psr:decision", f"uid:{uid}"],
    )
    payload = row.to_json()
    socketio.emit("mission_decision", payload, namespace="/socket.io")
    return jsonify({"success": True, "decision": payload})


