# ── Operational periods (смена) ──────────────────────────────────────


def _naive(dt):
    if dt is None:
        return None
    if getattr(dt, "tzinfo", None) is not None:
        return dt.astimezone(timezone.utc).replace(tzinfo=None)
    return dt


def _build_period_snapshot(mission_name: str, started_at, ended_at) -> dict:
    start = _naive(started_at)
    end = _naive(ended_at) or datetime.now(timezone.utc).replace(tzinfo=None)

    subjects = (
        db.session.execute(
            db.session.query(MissionSubject)
            .filter_by(mission_name=mission_name)
            .order_by(MissionSubject.created.desc())
        )
        .scalars()
        .all()
    )
    active_subj = next((s for s in subjects if s.status == "active"), subjects[0] if subjects else None)

    tasks = (
        db.session.execute(
            db.session.query(MissionTask).filter_by(mission_name=mission_name)
        )
        .scalars()
        .all()
    )
    task_rows = []
    for t in tasks:
        created = _naive(t.created)
        updated = _naive(t.updated)
        in_window = (created and start <= created <= end) or (updated and start <= updated <= end)
        still_open = (t.status or "") in ("issued", "acked", "overdue")
        if in_window or still_open:
            task_rows.append(t.to_json())

    roster = (
        db.session.execute(
            db.session.query(MissionRosterEntry).filter_by(mission_name=mission_name)
        )
        .scalars()
        .all()
    )
    roster_counts = {}
    for r in roster:
        st = r.status or "expected"
        roster_counts[st] = roster_counts.get(st, 0) + 1

    sectors = (
        db.session.execute(
            db.session.query(SearchSector).filter_by(mission_name=mission_name)
        )
        .scalars()
        .all()
    )
    sector_rows = [s.to_json() for s in sectors]
    sector_counts = {"active": 0, "cleared": 0}
    for s in sectors:
        if (s.status or "") == "cleared":
            sector_counts["cleared"] += 1
        else:
            sector_counts["active"] += 1

    logs = (
        db.session.execute(
            db.session.query(MissionLogEntry)
            .filter(
                MissionLogEntry.mission_name == mission_name,
                MissionLogEntry.created >= start,
                MissionLogEntry.created <= end,
            )
            .order_by(MissionLogEntry.created.asc())
            .limit(200)
        )
        .scalars()
        .all()
    )
    log_rows = [
        {
            "content": e.content,
            "keywords": e.keywords or [],
            "created": iso8601_string_from_datetime(e.created) if e.created else None,
            "creator_uid": e.creator_uid,
        }
        for e in logs
    ]

    track_rows = (
        db.session.query(Point.device_uid, db.func.count(Point.id))
        .filter(
            Point.device_uid.isnot(None),
            Point.timestamp >= start,
            Point.timestamp <= end,
        )
        .group_by(Point.device_uid)
        .all()
    )
    track_summary = {
        "devices": len(track_rows),
        "points": int(sum(c for _, c in track_rows)),
    }

    decisions = (
        db.session.execute(
            db.session.query(MissionHqDecision)
            .filter(
                MissionHqDecision.mission_name == mission_name,
                MissionHqDecision.created >= start,
                MissionHqDecision.created <= end,
            )
            .order_by(MissionHqDecision.created.asc())
        )
        .scalars()
        .all()
    )

    return {
        "window": {
            "started_at": iso8601_string_from_datetime(start),
            "ended_at": iso8601_string_from_datetime(end),
        },
        "subject": active_subj.to_json() if active_subj else None,
        "tasks": task_rows,
        "tasks_open": sum(
            1 for t in task_rows if (t.get("status") or "") in ("issued", "acked", "overdue")
        ),
        "roster": [r.to_json() for r in roster],
        "roster_counts": roster_counts,
        "sectors": sector_rows,
        "sector_counts": sector_counts,
        "logs": log_rows,
        "decisions": [d.to_json() for d in decisions],
        "track_summary": track_summary,
    }


def _format_period_report(period: MissionOpPeriod) -> str:
    snap = {}
    if period.snapshot_json:
        try:
            snap = json.loads(period.snapshot_json)
        except Exception:
            snap = {}
    lines = []
    lines.append("ПСР — ОТЧЁТ СМЕНЫ / HANDOFF")
    lines.append("=" * 40)
    lines.append(f"Операция: {period.mission_name}")
    lines.append(f"Смена: {period.label or period.uid}")
    lines.append(
        f"Окно: {iso8601_string_from_datetime(period.started_at) if period.started_at else '?'} → "
        f"{iso8601_string_from_datetime(period.ended_at) if period.ended_at else 'сейчас'}"
    )
    lines.append(f"Статус: {period.status}")
    if period.commander:
        lines.append(f"Командир смены: {period.commander}")
    if period.incoming_commander:
        lines.append(f"Принимает: {period.incoming_commander}")
    lines.append("")
    subj = snap.get("subject")
    if subj:
        lines.append("--- Ориентировка ---")
        lines.append(f"  {subj.get('full_name')} [{subj.get('status')}]")
        if subj.get("clothing"):
            lines.append(f"  Одежда: {subj['clothing']}")
        if subj.get("last_seen_place"):
            lines.append(f"  Где видели: {subj['last_seen_place']}")
        lines.append("")
    lines.append("--- Секторы ---")
    sc = snap.get("sector_counts") or {}
    lines.append(f"  активных: {sc.get('active', 0)}, пройдено: {sc.get('cleared', 0)}")
    for s in snap.get("sectors") or []:
        st = "пройден" if s.get("status") == "cleared" else "активен"
        asg = f" → {s.get('assigned_to')}" if s.get("assigned_to") else ""
        lines.append(f"  • {s.get('name')} — {st}{asg}")
    lines.append("")
    lines.append("--- Задания ---")
    lines.append(f"  в снимке: {len(snap.get('tasks') or [])}, открытых: {snap.get('tasks_open', 0)}")
    for t in snap.get("tasks") or []:
        asg = f" → {t.get('assignee')}" if t.get("assignee") else ""
        lines.append(f"  • [{t.get('status')}] {t.get('title')}{asg}")
    lines.append("")
    decisions = snap.get("decisions") or []
    if decisions:
        lines.append("--- Решения штаба ---")
        for d in decisions:
            who = f" ({d.get('created_by')})" if d.get("created_by") else ""
            lines.append(f"  • [{d.get('category')}]{who} {d.get('body')}")
        lines.append("")
    lines.append("--- Состав ---")
    rc = snap.get("roster_counts") or {}
    lines.append("  " + ", ".join(f"{k}: {v}" for k, v in rc.items()) if rc else "  (пусто)")
    for r in snap.get("roster") or []:
        lines.append(f"  • {r.get('display_name')} ({r.get('callsign') or '—'}) [{r.get('status')}]")
    lines.append("")
    ts = snap.get("track_summary") or {}
    lines.append(f"--- Треки --- устройств: {ts.get('devices', 0)}, точек GPS: {ts.get('points', 0)}")
    lines.append("")
    if period.summary:
        lines.append("--- Итог смены ---")
        lines.append(period.summary)
        lines.append("")
    if period.findings:
        lines.append("--- Находки / результат ---")
        lines.append(period.findings)
        lines.append("")
    if period.next_priorities:
        lines.append("--- Приоритеты следующей смены ---")
        lines.append(period.next_priorities)
        lines.append("")
    logs = snap.get("logs") or []
    if logs:
        lines.append(f"--- Журнал операции ({len(logs)}) ---")
        for e in logs[-40:]:
            lines.append(f"  [{e.get('created') or ''}] {e.get('content')}")
    lines.append("")
    lines.append("(Треки на карте: /map — выставьте окно по started_at смены)")
    return "\n".join(lines)


