@mission_ops_api.route("/api/missions/<path:mission_name>/periods", methods=["POST"])
@auth_required()
def create_period(mission_name):
    ensure_ops_tables()
    if not _mission_or_404(mission_name):
        return jsonify({"success": False, "error": gettext("Mission not found")}), 404
    existing_open = db.session.execute(
        db.session.query(MissionOpPeriod).filter_by(mission_name=mission_name, status="open")
    ).scalar_one_or_none()
    if existing_open:
        return jsonify({
            "success": False,
            "error": gettext("An open period already exists"),
            "open_uid": existing_open.uid,
        }), 409
    body = request.get_json(silent=True) or {}
    now = datetime.now(timezone.utc)
    started = _parse_dt(body.get("started_at")) or now
    uid = body.get("uid") or str(uuid.uuid4())
    label = (body.get("label") or "").strip()
    if not label:
        label = f"Смена {_naive(started).strftime('%d.%m %H:%M')}"
    now_n = _naive(now)
    period = MissionOpPeriod(
        uid=uid,
        mission_name=mission_name,
        label=label[:255],
        started_at=_naive(started),
        status="open",
        commander=(body.get("commander") or None),
        incoming_commander=(body.get("incoming_commander") or None),
        summary=(body.get("summary") or None),
        findings=(body.get("findings") or None),
        next_priorities=(body.get("next_priorities") or None),
        created_by=getattr(current_user, "username", None),
        created=now_n,
        updated=now_n,
    )
    db.session.add(period)
    db.session.commit()
    _add_mission_log(mission_name, f"Смена открыта: {period.label}", ["psr:period", f"uid:{uid}"])
    payload = period.to_json(include_snapshot=False)
    socketio.emit("mission_period", payload, namespace="/socket.io")
    return jsonify({"success": True, "period": payload})


@mission_ops_api.route("/api/missions/<path:mission_name>/periods/<uid>", methods=["GET"])
@auth_required()
def get_period(mission_name, uid):
    ensure_ops_tables()
    period = db.session.execute(
        db.session.query(MissionOpPeriod).filter_by(mission_name=mission_name, uid=uid)
    ).scalar_one_or_none()
    if not period:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    return jsonify({"success": True, "period": period.to_json(include_snapshot=True)})


@mission_ops_api.route("/api/missions/<path:mission_name>/periods/<uid>", methods=["PATCH"])
@auth_required()
def patch_period(mission_name, uid):
    ensure_ops_tables()
    period = db.session.execute(
        db.session.query(MissionOpPeriod).filter_by(mission_name=mission_name, uid=uid)
    ).scalar_one_or_none()
    if not period:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    body = request.get_json(silent=True) or {}
    for field in ("label", "commander", "incoming_commander", "summary", "findings", "next_priorities"):
        if field in body:
            setattr(period, field, body[field])
    if period.status == "open" and "started_at" in body:
        st = _parse_dt(body["started_at"])
        if st:
            period.started_at = _naive(st)
    period.updated = datetime.now(timezone.utc).replace(tzinfo=None)
    db.session.commit()
    payload = period.to_json(include_snapshot=False)
    socketio.emit("mission_period", payload, namespace="/socket.io")
    return jsonify({"success": True, "period": payload})


@mission_ops_api.route("/api/missions/<path:mission_name>/periods/<uid>/close", methods=["POST"])
@auth_required()
def close_period(mission_name, uid):
    ensure_ops_tables()
    period = db.session.execute(
        db.session.query(MissionOpPeriod).filter_by(mission_name=mission_name, uid=uid)
    ).scalar_one_or_none()
    if not period:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    if period.status == "closed":
        return jsonify({"success": False, "error": gettext("Already closed")}), 400
    body = request.get_json(silent=True) or {}
    for field in ("summary", "findings", "next_priorities", "commander", "incoming_commander", "label"):
        if field in body and body[field] is not None:
            setattr(period, field, body[field])
    ended = _parse_dt(body.get("ended_at")) or datetime.now(timezone.utc)
    period.ended_at = _naive(ended)
    period.status = "closed"
    snap = _build_period_snapshot(mission_name, period.started_at, period.ended_at)
    period.snapshot_json = json.dumps(snap, ensure_ascii=False)
    period.updated = datetime.now(timezone.utc).replace(tzinfo=None)
    db.session.commit()
    _add_mission_log(mission_name, f"Смена закрыта: {period.label}", ["psr:period", f"uid:{uid}"])
    payload = period.to_json(include_snapshot=True)
    socketio.emit("mission_period", payload, namespace="/socket.io")
    return jsonify({"success": True, "period": payload})


@mission_ops_api.route("/api/missions/<path:mission_name>/periods/<uid>/report", methods=["GET"])
@auth_required()
def period_report(mission_name, uid):
    ensure_ops_tables()
    period = db.session.execute(
        db.session.query(MissionOpPeriod).filter_by(mission_name=mission_name, uid=uid)
    ).scalar_one_or_none()
    if not period:
        return jsonify({"success": False, "error": gettext("Not found")}), 404
    # For open periods, build a live snapshot for the report body without persisting permanently
    if not period.snapshot_json:
        snap = _build_period_snapshot(mission_name, period.started_at, period.ended_at)
        # temporary for formatter
        period.snapshot_json = json.dumps(snap, ensure_ascii=False)
        text = _format_period_report(period)
        period.snapshot_json = None
    else:
        text = _format_period_report(period)
    return app.response_class(text, mimetype="text/plain; charset=utf-8")
